head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 동일한 chart 설정으로 sheetName 만 달리하여 advancedExcelDownload 실행
//  · 호출 시 전달한 객체에 엔진이 내부 값을 덧붙이므로 출력 문자열은 호출 전에 만들어 둔다.
scwin.runCase = function (strSheetName, strFileName) {
    var strShow = "\"" + strSheetName + "\"";

    target1.advancedExcelDownload({
        "fileName" : strFileName,
        "sheetName" : strSheetName,
        "chart" : {
            "chartName" : "pie",
            "title" : "Value Chart",
            "xTitle" : "Name",
            "yTitle" : "Value",
            "startRowIndex" : 6,
            "startColIndex" : 0,
            "endRowIndex" : 22,
            "endColIndex" : 8,
            "legend" : "true",
            "legendPosition" : "bottom",
            "catAxisRange" : { "startRowIndex" : 1, "startColIndex" : 0, "endRowIndex" : 4, "endColIndex" : 0 },
            "serAxisRange" : { "startRowIndex" : 0, "startColIndex" : 1, "endRowIndex" : 0, "endColIndex" : 1 },
            "dataAxisRange" : { "startRowIndex" : 1, "startColIndex" : 1, "endRowIndex" : 4, "endColIndex" : 1 }
        }
    });

    scwin.setReturnValue("sheetName : " + strShow);
    scwin.setReturnValue("파일명 : " + strFileName);
    scwin.setReturnValue("");
};



// sheetName "my sheet" (공백 포함)
scwin.btn_space_onclick = function () {
    scwin.runCase("my sheet", "dl_sheetName_space.xlsx");
};

// sheetName "mysheet" (공백 없음)
scwin.btn_nospace_onclick = function () {
    scwin.runCase("mysheet", "dl_sheetName_nospace.xlsx");
};
